FONTES = '<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Spectral:ital,wght@0,400;0,600;1,400&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap">'
ESTILO = '<style>\n:root{\n  --ground:#eef2f1; --surface:#ffffff; --surface-2:#e4ebe9;\n  --ink:#0f1d1c; --ink-2:#334744; --muted:#5f716f;\n  --line:#cbd8d5; --line-strong:#9fb3af;\n  --accent:#14655d; --accent-soft:#d5e6e3;\n  --alert:#9e3227; --alert-soft:#f2ded9;\n  --tint:20,101,93;\n  --shadow:0 1px 2px rgba(15,29,28,.06);\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme="light"]){\n    --ground:#0c1413; --surface:#131e1d; --surface-2:#1a2726;\n    --ink:#dfe8e5; --ink-2:#b3c4c1; --muted:#8aa09d;\n    --line:#27403d; --line-strong:#3d5b57;\n    --accent:#49a89b; --accent-soft:#17332f;\n    --alert:#d97a6c; --alert-soft:#33201d;\n    --tint:73,168,155;\n    --shadow:0 1px 2px rgba(0,0,0,.4);\n  }\n}\n:root[data-theme="dark"]{\n  --ground:#0c1413; --surface:#131e1d; --surface-2:#1a2726;\n  --ink:#dfe8e5; --ink-2:#b3c4c1; --muted:#8aa09d;\n  --line:#27403d; --line-strong:#3d5b57;\n  --accent:#49a89b; --accent-soft:#17332f;\n  --alert:#d97a6c; --alert-soft:#33201d;\n  --tint:73,168,155;\n  --shadow:0 1px 2px rgba(0,0,0,.4);\n}\n\n*{box-sizing:border-box}\nbody{\n  background:var(--ground); color:var(--ink);\n  font-family:"IBM Plex Sans",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;\n  font-size:16.5px; line-height:1.65; margin:0;\n  -webkit-font-smoothing:antialiased;\n}\n.wrap{\n  display:grid; grid-template-columns:\n    [full-start] minmax(1.25rem,1fr)\n    [wide-start] minmax(0,240px)\n    [text-start] minmax(0,64ch) [text-end]\n    minmax(0,240px) [wide-end]\n    minmax(1.25rem,1fr) [full-end];\n  row-gap:0;\n}\n.wrap > *{grid-column:text}\n.wide{grid-column:wide}\n.full{grid-column:full}\n\nh1,h2,h3{font-family:Spectral,Georgia,serif; font-weight:600; text-wrap:balance; margin:0}\nh1{font-size:clamp(2.1rem,4.6vw,3.1rem); line-height:1.08; letter-spacing:-.015em}\nh2{font-size:1.72rem; line-height:1.2; margin:0 0 .2rem}\nh3{font-size:1.12rem; line-height:1.3; margin:0 0 .35rem}\np{margin:0 0 1.05rem}\na{color:var(--accent)}\nstrong{font-weight:600}\ncode,.mono{font-family:"IBM Plex Mono",ui-monospace,monospace; font-size:.87em}\ncode{background:var(--surface-2); padding:.1em .32em; border-radius:3px}\n\n/* ---------- cabecalho ---------- */\nheader{padding:clamp(3rem,7vw,5.5rem) 0 2.2rem}\n.eyebrow{\n  font-family:"IBM Plex Mono",monospace; font-size:.74rem; letter-spacing:.14em;\n  text-transform:uppercase; color:var(--accent); margin:0 0 1.1rem\n}\n.standfirst{\n  font-family:Spectral,Georgia,serif; font-size:1.22rem; line-height:1.55;\n  color:var(--ink-2); margin:1.3rem 0 0; max-width:56ch\n}\n.meta{\n  display:flex; flex-wrap:wrap; gap:0 2.4rem; margin:2.2rem 0 0;\n  padding-top:1.2rem; border-top:1px solid var(--line);\n  font-size:.86rem; color:var(--muted)\n}\n.meta div{display:flex; flex-direction:column; gap:.1rem}\n.meta b{\n  font-family:"IBM Plex Mono",monospace; font-weight:500; font-size:1.15rem;\n  color:var(--ink); font-variant-numeric:tabular-nums\n}\n\n/* ---------- secoes ---------- */\nsection{padding:2.6rem 0 .4rem}\n.sec-head{display:flex; align-items:baseline; gap:.85rem; margin:0 0 1.1rem}\n.sec-num{\n  font-family:"IBM Plex Mono",monospace; font-size:.8rem; color:var(--muted);\n  border:1px solid var(--line-strong); border-radius:2px; padding:.05rem .4rem;\n  flex:none; position:relative; top:-.22rem\n}\n.lede{color:var(--ink-2)}\n\n/* ---------- destaque do achado ---------- */\n.achado{\n  background:var(--alert-soft); border-left:3px solid var(--alert);\n  padding:1.3rem 1.5rem; margin:0 0 1.4rem\n}\n.achado p:last-child{margin-bottom:0}\n.achado .grande{\n  font-family:Spectral,Georgia,serif; font-size:2.5rem; line-height:1;\n  color:var(--alert); font-variant-numeric:tabular-nums; display:block; margin-bottom:.3rem\n}\n\n/* ---------- tabelas ---------- */\n.tabela{overflow-x:auto; margin:0 0 .6rem}\ntable{border-collapse:collapse; width:100%; font-size:.9rem}\ncaption{\n  caption-side:top; text-align:left; color:var(--muted); font-size:.82rem;\n  padding:0 0 .55rem\n}\nth,td{\n  padding:.44rem .7rem; text-align:right; border-bottom:1px solid var(--line);\n  font-variant-numeric:tabular-nums; white-space:nowrap\n}\nth:first-child,td:first-child{text-align:left; white-space:normal}\nthead th{\n  font-size:.74rem; letter-spacing:.07em; text-transform:uppercase; color:var(--muted);\n  font-weight:500; border-bottom:1px solid var(--line-strong)\n}\ntbody tr:last-child td{border-bottom:none}\ntr.destaque td{background:var(--accent-soft)}\ntr.destaque td:first-child{font-weight:600}\ntd.num{font-family:"IBM Plex Mono",monospace}\n.t1{background:rgba(var(--tint),.07)} .t2{background:rgba(var(--tint),.15)}\n.t3{background:rgba(var(--tint),.24)} .t4{background:rgba(var(--tint),.34)}\n.t5{background:rgba(var(--tint),.46)} .t6{background:rgba(var(--tint),.6)}\n.legenda{font-size:.82rem; color:var(--muted); margin:.1rem 0 1.4rem}\n\n/* ---------- fluxograma da coorte ---------- */\n.fluxo{\n  font-family:"IBM Plex Mono",monospace; font-size:.86rem; line-height:2;\n  border-top:1px solid var(--line); margin:.4rem 0 1.3rem\n}\n.fluxo div{\n  display:flex; justify-content:space-between; gap:1rem; align-items:baseline;\n  border-bottom:1px solid var(--line); padding:.15rem 0\n}\n.fluxo .saiu{color:var(--alert); padding-left:1.4rem}\n.fluxo .fica{font-weight:500}\n.fluxo b{font-variant-numeric:tabular-nums}\n\n/* ---------- fases do pipeline ---------- */\n.fases{display:flex; flex-direction:column; gap:0; margin:.5rem 0 1.4rem}\n.fase{\n  display:grid; grid-template-columns:2.4rem 1fr; gap:0 1rem;\n  padding:1rem 0; border-top:1px solid var(--line)\n}\n.fase:last-child{border-bottom:1px solid var(--line)}\n.fase .n{\n  font-family:"IBM Plex Mono",monospace; font-size:.95rem; color:var(--accent);\n  font-weight:500\n}\n.fase p{margin:.25rem 0 0; font-size:.94rem; color:var(--ink-2)}\n.fase .porque{\n  margin-top:.5rem; font-size:.88rem; color:var(--muted);\n  border-left:2px solid var(--line-strong); padding-left:.75rem\n}\n\n/* ---------- figuras ---------- */\nfigure{margin:1.6rem 0 1.9rem; background:var(--surface); padding:1rem;\n  border:1px solid var(--line); box-shadow:var(--shadow)}\nfigure img{width:100%; height:auto; display:block}\nfigcaption{\n  font-size:.85rem; color:var(--muted); margin-top:.85rem; line-height:1.5;\n  padding-top:.7rem; border-top:1px solid var(--line)\n}\nfigcaption b{color:var(--ink-2); font-weight:500}\n\n/* ---------- lista de ressalvas ---------- */\nol.ressalvas{margin:0 0 1.2rem; padding-left:0; list-style:none; counter-reset:r}\nol.ressalvas li{\n  counter-increment:r; padding:.85rem 0 .85rem 2.3rem; position:relative;\n  border-bottom:1px solid var(--line); font-size:.95rem\n}\nol.ressalvas li::before{\n  content:counter(r); position:absolute; left:0; top:.85rem;\n  font-family:"IBM Plex Mono",monospace; font-size:.8rem; color:var(--muted)\n}\nol.ressalvas li:first-child{border-top:1px solid var(--line)}\n\n/* ---------- arquivos ---------- */\n.arquivos{\n  font-family:"IBM Plex Mono",monospace; font-size:.83rem; line-height:1.9;\n  background:var(--surface); border:1px solid var(--line); padding:1rem 1.2rem;\n  overflow-x:auto\n}\n.arquivos span{color:var(--muted)}\n\nfooter{\n  margin-top:3rem; padding:1.5rem 0 4rem; border-top:1px solid var(--line);\n  font-size:.84rem; color:var(--muted)\n}\nhr.fina{border:none; border-top:1px solid var(--line); margin:2.4rem 0 0}\n\n/* ---------- acoes de saida ---------- */\n.acoes{\n  display:flex; flex-wrap:wrap; align-items:center; gap:.6rem;\n  margin:1.6rem 0 0\n}\n.acoes button{\n  font-family:"IBM Plex Sans",sans-serif; font-size:.85rem; color:var(--ink);\n  background:var(--surface); border:1px solid var(--line-strong); border-radius:2px;\n  padding:.42rem .85rem; cursor:pointer; transition:background .12s, border-color .12s\n}\n.acoes button:hover{background:var(--accent-soft); border-color:var(--accent)}\n.acoes button:focus-visible{outline:2px solid var(--accent); outline-offset:2px}\n.acoes button:disabled{opacity:.5; cursor:default}\n.acoes button.principal{\n  background:var(--accent); border-color:var(--accent); color:var(--surface); font-weight:500\n}\n.acoes button.principal:hover{filter:brightness(1.1)}\n.acoes .aviso{font-size:.82rem; color:var(--muted)}\n\n@media print{\n  :root{\n    --ground:#fff; --surface:#fff; --surface-2:#f1f1f0;\n    --ink:#111; --ink-2:#333; --muted:#555;\n    --line:#ccc; --line-strong:#999;\n    --accent:#14655d; --accent-soft:#e9f1ef;\n    --alert:#9e3227; --alert-soft:#f8ece9;\n    --tint:20,101,93; --shadow:none;\n  }\n  .wrap{display:block; max-width:44rem; margin:0 auto}\n  .acoes{display:none}\n  figure{break-inside:avoid}\n  h1,h2,h3{break-after:avoid}\n  tr,.fase,ol.ressalvas li{break-inside:avoid}\n  header{padding-top:0}\n  section{padding-top:1.6rem}\n}\n\n@media (max-width:900px){\n  .wrap{grid-template-columns:[full-start wide-start text-start] 1fr [text-end wide-end full-end];\n    padding:0 1.15rem}\n  body{font-size:16px}\n  .meta{gap:.9rem 1.8rem}\n}\n@media (prefers-reduced-motion:reduce){*{animation:none!important; transition:none!important}}\n</style>'
SCRIPT = '<script>\n(function () {\n  var botao = document.getElementById("baixar");\n  var aviso = document.getElementById("aviso");\n\n  // Imprimir funciona em qualquer lugar, inclusive numa copia salva fora do claude.ai.\n  document.getElementById("imprimir").addEventListener("click", function () {\n    window.print();\n  });\n\n  // O sandbox bloqueia download que a propria pagina dispara, entao o arquivo sai pela\n  // capability downloads, que mostra uma confirmacao para quem esta lendo.\n  if (!window.claude || typeof window.claude.use !== "function") return;\n\n  window.claude.use("downloads").then(function (downloads) {\n    if (!downloads) return;          // sem a capability, fica so o PDF\n    botao.hidden = false;\n\n    botao.addEventListener("click", function () {\n      botao.disabled = true;\n      aviso.textContent = "";\n\n      // Serializa uma copia, e nao o DOM vivo: na copia o botao volta a ficar escondido,\n      // porque fora do claude.ai ele nao teria como funcionar.\n      var copia = document.documentElement.cloneNode(true);\n      var botaoCopia = copia.querySelector("#baixar");\n      if (botaoCopia) botaoCopia.setAttribute("hidden", "");\n      var avisoCopia = copia.querySelector("#aviso");\n      if (avisoCopia) avisoCopia.textContent = "";\n\n      downloads.save({\n        filename: "predicao-obito-endocardite.html",\n        data: "<!doctype html>\\n" + copia.outerHTML\n      }).then(function () {\n        aviso.textContent = "Arquivo salvo.";\n      }).catch(function (erro) {\n        var codigo = erro && erro.code;\n        if (codigo === "declined") {\n          aviso.textContent = "";\n        } else if (codigo === "rate_limited") {\n          aviso.textContent = "Já existe um pedido aberto. Tente de novo em instantes.";\n        } else {\n          aviso.textContent = "Não foi possível salvar. Use Salvar em PDF.";\n        }\n      }).then(function () {\n        botao.disabled = false;\n      });\n    });\n  });\n})();\n</script>'
